class OnboardingScreen extends StatelessWidget { const OnboardingScreen({super.key}); @override Widget build(BuildContext context){ final pages=[('Detect Urban Crises Instantly','Monitor citizen reports, traffic, weather and emergency feeds in real time.',Icons.warning_amber_rounded),('AI Agents That Think and Plan','Detection, severity, planning, dispatch and alert agents coordinate response.',Icons.hub),('Built for Pakistan’s Smart Cities','From Karachi floods to Lahore traffic incidents, CIVIX AI helps cities respond faster.',Icons.location_city)]; return GradientShell(child:Scaffold(body:PageView.builder(itemCount:3,itemBuilder:(c,i)=>Padding(padding:const EdgeInsets.all(28),child:Column(mainAxisAlignment:MainAxisAlignment.center,children:[Icon(pages[i].$3,size:120,color:CivixColors.cyan),const SizedBox(height:28),Text(pages[i].$1,textAlign:TextAlign.center,style:Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight:FontWeight.w800)),const SizedBox(height:14),Text(pages[i].$2,textAlign:TextAlign.center,style:const TextStyle(color:CivixColors.muted,fontSize:16)),const SizedBox(height:36),if(i==2)NeonButton(label:'Start CIVIX Demo',icon:Icons.arrow_forward,onTap:()=>context.go('/login'))])))));}}
